.filter-row td { 
    background: #eeeeee !important; 
    padding: 5px; 
} 
 
.filter-row input, 
.filter-row select { 
    width: 100%; 
    height: 29px; 
    border: 1px solid #cccccc; 
    border-radius: 2px; 
    background: #ffffff; 
    font-size: 12px; 
    padding: 3px 5px; 
} 
 
.course-image { 
    width: 62px; 
    height: 48px; 
    object-fit: cover; 
    display: block; 
    margin: auto; 
    border: 1px solid #dddddd; 
} 
 
.course-title { 
    font-weight: 600; 
    color: #333333; 
} 
 
.course-category { 
    line-height: 1.4; 
} 
 
.course-teacher { 
    white-space: nowrap; 
} 
 
.empty-teacher { 
    color: #999999; 
} 
 
.test-button { 
    display: inline-block; 
    background: #eeeeee; 
    color: #333333; 
    border: 1px solid #cccccc; 
    padding: 3px 6px; 
    border-radius: 2px; 
    font-size: 11px; 
    text-decoration: none; 
    white-space: nowrap; 
} 
 
.test-button:hover { 
    background: #dddddd; 
    color: #222222; 
} 
 
.priority-handle { 
    cursor: move; 
    color: #777777; 
    font-size: 16px; 
} 
 
.action-buttons { 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 4px; 
} 
 
.action-button { 
    width: 30px; 
    height: 29px; 
    display: inline-flex; 
    align-items: center; 
    justify-content: center; 
    border: 0; 
    border-radius: 3px; 
    color: #ffffff; 
    text-decoration: none; 
    cursor: pointer; 
} 
 
.view-button { 
    background: #17a2b8; 
} 
 
.edit-button { 
    background: #168bea; 
} 
 
.delete-button { 
    background: #dc3545; 
} 
 
.action-button:hover { 
    opacity: 0.85; 
    color: #ffffff; 
} 
 
 
/* ========================================================= 
   PAGINATION 
========================================================= */ 
 
.course-pagination-wrapper { 
    display: flex; 
    justify-content: flex-end; 
    padding-top: 15px; 
} 
 
.course-pagination { 
    display: flex; 
    align-items: center; 
    list-style: none; 
    margin: 0; 
    padding: 0; 
} 
 
.course-pagination li { 
    margin: 0 2px; 
} 
 
.course-pagination button { 
    min-width: 34px; 
    height: 32px; 
    padding: 4px 9px; 
    border: 1px solid #cccccc; 
    background: #ffffff; 
    color: #333333; 
    font-size: 13px; 
    border-radius: 2px; 
    cursor: pointer; 
} 
 
.course-pagination button:hover { 
    background: #eeeeee; 
} 
 
.course-pagination li.active button { 
    background: #168bea; 
    border-color: #168bea; 
    color: #ffffff; 
} 
 
.course-pagination li.disabled button { 
    display: none; 
} 
 
 
/* ========================================================= 
   DELETE ALL 
========================================================= */ 
 
.course-bottom-actions { 
    margin-top: 4px; 
} 
 
.delete-all-button { 
    border: 0; 
    background: #168bea; 
    color: #ffffff; 
    padding: 7px 14px; 
    border-radius: 3px; 
    font-size: 14px; 
    cursor: pointer; 
} 
 
.delete-all-button:hover { 
    background: #087bd7; 
} 
 
 
/* ========================================================= 
   RESPONSIVE 
========================================================= */ 
 
@media (max-width: 992px) { 
 
    .course-content { 
        padding: 12px; 
    } 
 
    .course-search-input { 
        width: 65%; 
    } 
 
} 
 
 
@media (max-width: 768px) { 
 
    .course-page-header-inner { 
        padding: 12px 16px; 
    } 
 
    .course-page-header h1 { 
        font-size: 20px; 
    } 
 
    .course-breadcrumb { 
        font-size: 13px; 
    } 
 
    .course-content { 
        padding: 10px; 
    } 
 
    .search-row { 
        display: block; 
    } 
 
    .search-row label { 
        display: block; 
        width: 100%; 
        margin-bottom: 5px; 
    } 
 
    .course-search-input { 
        width: 100%; 
        max-width: none; 
    } 
 
    .search-button-row { 
        margin-left: 0; 
    } 
 
    .showing-row { 
        align-items: flex-end; 
        padding: 10px 0; 
    } 
 
