        justify-content: center; 
        overflow-x: auto; 
    } 
 
} 
 
 
@media (max-width: 480px) { 
 
    .course-page-header { 
        min-height: 65px; 
    } 
 
    .course-page-header h1 { 
        font-size: 18px; 
    } 
 
