        min-width: 110px; 
    } 
 
} 
 
 
/* ========================================================= 
   HIDE NUMBER INPUT ARROWS IF USED 
========================================================= */ 
 
input::-webkit-outer-spin-button, 
input::-webkit-inner-spin-button { 
    -webkit-appearance: none; 
    margin: 0; 
} 
 
</style> 
 
<script> 
 
/* ========================================================= 
   COURSE DATA 
========================================================= */ 
 
const courses = <?= json_encode( 
    $courses, 
    JSON_UNESCAPED_UNICODE | 
    JSON_UNESCAPED_SLASHES 
); ?>; 
 
 
/* ========================================================= 
   PAGINATION SETTINGS 
========================================================= */ 
 
/* 
    10 รายการ 
    4 รายการ / หน้า 
 
    หน้า 1 = รายการ 1 - 4 
    หน้า 2 = รายการ 5 - 8 
    หน้า 3 = รายการ 9 - 10 
 
    แต่ละหน้าจะแสดงข้อมูลของหน้าตัวเองจริง ๆ 
*/ 
 
let currentPage = 1; 
 
let itemsPerPage = 10; 
 
 
/* ========================================================= 
   FILTERED DATA 
========================================================= */ 
 
let filteredCourses = [...courses]; 
 
 
/* ========================================================= 
   DOM 
========================================================= */ 
 
const tableBody = 
    document.getElementById('courseTableBody'); 
 
const pagination = 
    document.getElementById('coursePagination'); 
 
const selectAll = 
    document.getElementById('selectAllCourses'); 
 
 
/* ========================================================= 
   RENDER TABLE 
========================================================= */ 
 
function renderTable() { 
 
    tableBody.innerHTML = ''; 
 
    const startIndex = 
        (currentPage - 1) * itemsPerPage; 
 
    const endIndex = 
        startIndex + itemsPerPage; 
 
    const pageCourses = 
        filteredCourses.slice(startIndex, endIndex); 
 
 
    if (pageCourses.length === 0) { 
 
        const row = 
            document.createElement('tr'); 
 
        row.innerHTML = ` 
            <td colspan="10" 
                style="text-align:center;padding:25px;color:#888;"> 
                No course found 
            </td> 
        `; 
 
        tableBody.appendChild(row); 
 
        return; 
    } 
 
 
    pageCourses.forEach(course => { 
 
        const row = 
            document.createElement('tr'); 
 
        row.dataset.id = course.id; 
 
        row.innerHTML = ` 
 
            <!-- CHECKBOX --> 
 
            <td style="text-align:center;"> 
 
                <input 
                    type="checkbox" 
                    class="course-checkbox" 
                    value="${course.id}" 
                > 
 
            </td> 
 
 
            <!-- IMAGE --> 
 
            <td style="text-align:center;"> 
 
                <img 
                    src="${course.image}" 
                    alt="${escapeHtml(course.title)}" 
                    class="course-image" 
                    onerror="this.src='assets/img/default-course.png';" 
                > 
 
            </td> 
 
 
            <!-- TITLE --> 
 
            <td> 
 
                <div class="course-title"> 
                    ${escapeHtml(course.title)} 
                </div> 
 
            </td> 
 
 
            <!-- PRE TEST --> 
 
            <td style="text-align:center;"> 
 
                <a 
                    href="#" 
                    class="test-button" 
                    onclick="return false;" 
                > 
                    Select (${course.pre}) 
                </a> 
 
            </td> 
 
 
            <!-- POST TEST --> 
 
            <td style="text-align:center;"> 
 
                <a 
                    href="#" 
                    class="test-button" 
                    onclick="return false;" 
                > 
                    Select (${course.post}) 
                </a> 
 
            </td> 
 
 
            <!-- SURVEY --> 
 
            <td style="text-align:center;"> 
 
                <a 
                    href="#" 
                    class="test-button" 
                    onclick="return false;" 
                > 
                    Select (${course.survey}) 
                </a> 
 
            </td> 
 
 
            <!-- CATEGORY --> 
 
            <td> 
 
                <div class="course-category"> 
                    ${escapeHtml(course.category)} 
                </div> 
 
            </td> 
 
 
            <!-- TEACHER --> 
 
            <td> 
 
                ${ 
                    course.teacher 
                    ? `<span class="course-teacher"> 
                            ${escapeHtml(course.teacher)} 
                       </span>` 
                    : `<span class="empty-teacher">-</span>` 
                } 
 
            </td> 
 
 
            <!-- PRIORITY --> 
 
            <td style="text-align:center;"> 
 
                <i 
                    class="bi bi-grip-vertical priority-handle" 
                    title="Drag to change priority" 
                ></i> 
 
            </td> 
 
 
            <!-- ACTION --> 
 
            <td> 
 
                <div class="action-buttons"> 
 
                    <a 
                        href="#" 
                        class="action-button view-button" 
                        title="View" 
                        onclick="return false;" 
                    > 
                        <i class="bi bi-eye"></i> 
                    </a> 
 
                    <a 
                        href="course-add.php?id=${course.id}" 
                        class="action-button edit-button" 
                        title="Edit" 
                    > 
                        <i class="bi bi-pencil"></i> 
                    </a> 
 
                    <button 
                        type="button" 
                        class="action-button delete-button" 
                        title="Delete" 
                        onclick="deleteCourse(${course.id})" 
                    > 
                        <i class="bi bi-trash"></i> 
                    </button> 
 
                </div> 
 
            </td> 
 
        `; 
 
        tableBody.appendChild(row); 
 
    }); 
 
 
    updateSelectAll(); 
 
} 
 
 
/* ========================================================= 
   PAGINATION 
========================================================= */ 
 
function renderPagination() { 
 
    pagination.innerHTML = ''; 
 
    const totalPages = 
        Math.ceil( 
            filteredCourses.length / 
            itemsPerPage 
        ); 
 
 
    /* 
        ถ้าไม่มีข้อมูล 
    */ 
 
    if (totalPages <= 0) { 
        return; 
    } 
 
 
    /* 
        ป้องกัน currentPage เกินจำนวนหน้า 
    */ 
 
    if (currentPage > totalPages) { 
        currentPage = totalPages; 
    } 
 
 
    /* 
        ===================================================== 
        FIRST 
        แสดงเฉพาะเมื่อไม่ได้อยู่หน้า 1 
        ===================================================== 
    */ 
 
    if (currentPage !== 1) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                'First', 
                1 
            ) 
        ); 
 
    } 
 
 
    /* 
        ===================================================== 
        PREVIOUS 
        แสดงเฉพาะเมื่อไม่ได้อยู่หน้า 1 
        ===================================================== 
    */ 
 
    if (currentPage !== 1) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                'Previous', 
                currentPage - 1 
            ) 
        ); 
 
    } 
 
 
    /* 
        ===================================================== 
        PAGE 1 
        ===================================================== 
    */ 
 
    pagination.appendChild( 
        createPaginationButton( 
            '1', 
            1, 
            currentPage === 1 
        ) 
    ); 
 
 
    /* 
        ===================================================== 
        PAGE 2 
        ===================================================== 
    */ 
 
    if (totalPages >= 2) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                '2', 
                2, 
                currentPage === 2 
            ) 
        ); 
 
    } 
 
 
    /* 
        ===================================================== 
        PAGE 3 
        ===================================================== 
    */ 
 
    if (totalPages >= 3) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                '3', 
                3, 
                currentPage === 3 
            ) 
        ); 
 
    } 
 
 
    /* 
        ===================================================== 
        NEXT 
        แสดงเฉพาะเมื่อไม่ได้อยู่หน้าสุดท้าย 
        ===================================================== 
    */ 
 
    if (currentPage !== totalPages) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                'Next', 
                currentPage + 1 
            ) 
        ); 
 
    } 
 
 
    /* 
        ===================================================== 
        LAST 
        แสดงเฉพาะเมื่อไม่ได้อยู่หน้าสุดท้าย 
        ===================================================== 
    */ 
 
    if (currentPage !== totalPages) { 
 
        pagination.appendChild( 
            createPaginationButton( 
                'Last', 
                totalPages 
            ) 
        ); 
 
    } 
 
} 
 
 
/* ========================================================= 
   CREATE PAGINATION BUTTON 
========================================================= */ 
 
function createPaginationButton( 
    text, 
    page, 
    active = false 
) { 
 
    const li = 
        document.createElement('li'); 
 
    if (active) { 
        li.classList.add('active'); 
    } 
 
    const button = 
        document.createElement('button'); 
 
    button.type = 'button'; 
 
    button.textContent = text; 
 
    button.addEventListener( 
        'click', 
        function () { 
 
            if ( 
                page === currentPage || 
                page < 1 
            ) { 
                return; 
            } 
 
            currentPage = page; 
 
            renderTable(); 
 
            renderPagination(); 
 
            window.scrollTo({ 
                top: 0, 
                behavior: 'smooth' 
            }); 
 
        } 
    ); 
 
    li.appendChild(button); 
 
    return li; 
} 
 
 
/* ========================================================= 
   SEARCH 
========================================================= */ 
 
document 
    .getElementById('courseSearchForm') 
    .addEventListener( 
        'submit', 
        function (event) { 
 
            event.preventDefault(); 
 
            applyFilters(); 
 
        } 
    ); 
 
 
/* ========================================================= 
   TABLE FILTER 
========================================================= */ 
 
document 
    .getElementById('tableTitleFilter') 
    .addEventListener( 
        'input', 
        applyFilters 
    ); 
 
 
document 
    .getElementById('tableCategoryFilter') 
    .addEventListener( 
        'input', 
        applyFilters 
    ); 
 
 
document 
    .getElementById('tableTeacherFilter') 
    .addEventListener( 
        'change', 
        applyFilters 
    ); 
 
 
/* ========================================================= 
   APPLY FILTERS 
========================================================= */ 
 
function applyFilters() { 
 
    const category = 
        document 
            .getElementById('searchCategory') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const number = 
        document 
            .getElementById('searchNumber') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const teacher = 
        document 
            .getElementById('searchTeacher') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const title = 
        document 
            .getElementById('searchTitle') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const tableTitle = 
        document 
            .getElementById('tableTitleFilter') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const tableCategory = 
        document 
            .getElementById('tableCategoryFilter') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    const tableTeacher = 
        document 
            .getElementById('tableTeacherFilter') 
            .value 
            .trim() 
            .toLowerCase(); 
 
 
    filteredCourses = 
        courses.filter(course => { 
 
            const matchesCategory = 
                !category || 
                course.category 
                    .toLowerCase() 
                    .includes(category); 
 
 
            const matchesNumber = 
                !number || 
                String(course.id) 
                    .toLowerCase() 
                    .includes(number); 
 
 
            const matchesTeacher = 
                !teacher || 
                course.teacher 
                    .toLowerCase() 
                    .includes(teacher); 
 
 
            const matchesTitle = 
                !title || 
                course.title 
                    .toLowerCase() 
                    .includes(title); 
 
 
            const matchesTableTitle = 
                !tableTitle || 
                course.title 
                    .toLowerCase() 
                    .includes(tableTitle); 
 
 
            const matchesTableCategory = 
                !tableCategory || 
                course.category 
                    .toLowerCase() 
                    .includes(tableCategory); 
 
 
            const matchesTableTeacher = 
                !tableTeacher || 
                course.teacher 
                    .toLowerCase() 
                    .includes(tableTeacher); 
 
 
            return ( 
                matchesCategory && 
                matchesNumber && 
                matchesTeacher && 
                matchesTitle && 
                matchesTableTitle && 
                matchesTableCategory && 
                matchesTableTeacher 
            ); 
 
        }); 
 
 
    /* 
        หลัง Search ให้กลับหน้า 1 
    */ 
 
    currentPage = 1; 
 
    renderTable(); 
 
    renderPagination(); 
 
} 
 
 
/* ========================================================= 
   SHOWING 
========================================================= */ 
 
document 
    .getElementById('showingCount') 
    .addEventListener( 
        'change', 
        function () { 
 
            /* 
                สำหรับหน้าตาม Inspector 
                ค่า Default / 10 ยังคงใช้ 4 รายการ 
                เพื่อให้ข้อมูลตัวอย่าง 10 รายการมี 3 หน้า 
            */ 
 
            if ( 
                this.value === '10' 
            ) { 
 
                itemsPerPage = 10; 
 
            } else { 
 
                itemsPerPage = 
                    parseInt( 
                        this.value, 
                        10 
                    ); 
 
            } 
 
 
            currentPage = 1; 
 
            renderTable(); 
 
            renderPagination(); 
 
        } 
    ); 
 
 
/* ========================================================= 
   SELECT ALL 
========================================================= */ 
 
selectAll.addEventListener( 
    'change', 
    function () { 
 
        const checkboxes = 
            document.querySelectorAll( 
                '.course-checkbox' 
            ); 
 
        checkboxes.forEach( 
            checkbox => { 
 
                checkbox.checked = 
                    selectAll.checked; 
 
            } 
        ); 
 
    } 
); 
 
 
/* ========================================================= 
   UPDATE SELECT ALL 
========================================================= */ 
 
function updateSelectAll() { 
 
    const checkboxes = 
        document.querySelectorAll( 
            '.course-checkbox' 
        ); 
 
    if (checkboxes.length === 0) { 
 
        selectAll.checked = false; 
 
        return; 
    } 
 
 
    const checked = 
        document.querySelectorAll( 
            '.course-checkbox:checked' 
        ).length; 
 
 
    selectAll.checked = 
        checked === checkboxes.length; 
 
} 
 
 
/* ========================================================= 
   DELETE COURSE 
========================================================= */ 
 
function deleteCourse(id) { 
 
    const course = 
        courses.find( 
            item => item.id === id 
        ); 
 
    if (!course) { 
        return; 
    } 
 
 
    const confirmed = 
        confirm( 
            'Delete course "' + 
            course.title + 
            '"?' 
        ); 
 
 
    if (!confirmed) { 
        return; 
    } 
 
 
    alert( 
        'Delete action for course ID ' + 
        id + 
        ' is ready for backend connection.' 
    ); 
 
} 
 
 
/* ========================================================= 
   DELETE ALL 
========================================================= */ 
 
document 
    .getElementById('deleteAllButton') 
    .addEventListener( 
        'click', 
        function () { 
 
            const selected = 
                Array.from( 
                    document.querySelectorAll( 
                        '.course-checkbox:checked' 
                    ) 
                ); 
 
 
            if (selected.length === 0) { 
 
                alert( 
                    'Please select at least one course.' 
                ); 
 
                return; 
            } 
 
 
            const confirmed = 
                confirm( 
                    'Delete selected courses?' 
                ); 
 
 
            if (!confirmed) { 
                return; 
            } 
 
 
            alert( 
                selected.length + 
                ' course(s) selected for deletion.' 
            ); 
 
        } 
    ); 
 
 
/* ========================================================= 
   ADVANCED SEARCH TOGGLE 
========================================================= */ 
 
document 
    .getElementById('advancedSearchToggle') 
    .addEventListener( 
        'click', 
        function () { 
 
            const body = 
                document.getElementById( 
                    'advancedSearchBody' 
                ); 
 
 
            body.classList.toggle('show'); 
 
            this.classList.toggle('open'); 
 
        } 
    ); 
 
 
/* ========================================================= 
   ESCAPE HTML 
========================================================= */ 
 
function escapeHtml(value) { 
 
    return String(value) 
        .replace( 
            /&/g, 
            '&amp;' 
        ) 
        .replace( 
            /</g, 
            '&lt;' 
        ) 
        .replace( 
            />/g, 
            '&gt;' 
        ) 
        .replace( 
            /"/g, 
            '&quot;' 
        ) 
        .replace( 
            /'/g, 
            '&#039;' 
        ); 
 
} 
 
 
/* ========================================================= 
   INITIAL LOAD 
========================================================= */ 
 
renderTable(); 
 
renderPagination(); 
 
</script> 
 
</body> 
</html> 
